class GymScreenState extends State<GymScreen>{List<WorkoutPlan> plans=[];List<ExerciseInfo> custom=[];int _historyRefresh=0;@override void initState(){super.initState();load();}Future<void> load()async{plans=(await StorageService.read('workout_plans')).map(WorkoutPlan.fromJson).toList();custom=(await StorageService.read('exercise_library')).map((e)=><String,String>{'name':'${e['name']??''}','muscle':'${e['muscle']??'Outros'}','equipment':'${e['equipment']??''}','description':'${e['description']??''}','imagePath':'${e['imagePath']??''}'}).where((e)=>e['name']!.isNotEmpty).toList();if(mounted)setState(()=>_historyRefresh++);}Future<void> refresh()async{await load();}List<ExerciseInfo> get library{final all=<ExerciseInfo>[...defaultExercises.map((e)=><String,String>{'name':e[0],'muscle':e[1],'equipment':'','description':'','imagePath':''}),...custom];final seen=<String>{};return all.where((e)=>seen.add(e['name']!.toLowerCase())).toList();}Future<ExerciseInfo?> newExercise()async{final result=await showDialog<ExerciseInfo>(context:context,builder:(_)=>const NewExerciseDialog());if(result==null)return null;if(!library.any((e)=>e['name']!.toLowerCase()==result['name']!.toLowerCase())){custom.add(result);await StorageService.write('exercise_library',custom);}return result;}Future<void> savePlans()=>StorageService.write('workout_plans',plans.map((e)=>e.toJson()).toList());Future<void> editPlan([WorkoutPlan? old])async{final draft=await Navigator.push<WorkoutPlanDraft>(context,MaterialPageRoute(builder:(_)=>PlanEditor(old:old,library:library,newExercise:newExercise)));if(draft==null)return;final p=old??WorkoutPlan(id:DateTime.now().microsecondsSinceEpoch.toString(),name:draft.name,weekdays:[],dayExercises:{});p.name=draft.name;p.weekdays=draft.weekdays.toList()..sort();p.dayExercises=draft.dayExercises;if(old==null)plans.add(p);await savePlans();if(mounted)setState((){});}Future<void> deletePlan(WorkoutPlan p)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Excluir treino?'),content:Text('Excluir ${p.name}? O histórico será preservado.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Excluir'))]));if(ok==true){plans.removeWhere((x)=>x.id==p.id);await savePlans();if(mounted)setState((){});}}Future<void> startWorkout(WorkoutPlan p,int day)async{final ex=p.exercisesFor(day).map((e)=>Exercise(id:e.id,name:e.name,muscle:e.muscle,sets:e.sets,reps:e.reps)).toList();if(ex.isEmpty)return;await Navigator.push(context,MaterialPageRoute(builder:(_)=>WorkoutExecution(name:p.name,weekday:day,exercises:ex)));if(mounted)await load();}@override Widget build(BuildContext context){final today=DateTime.now().weekday;return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Academia',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text('${plans.length} treino(s) configurado(s)')])),FilledButton.icon(onPressed:()=>editPlan(),icon:const Icon(Icons.add),label:const Text('Criar treino'))]),const SizedBox(height:12),if(plans.isEmpty)const AppCard(child:Text('Nenhum treino criado.')),for(final p in plans)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.fitness_center),const SizedBox(width:8),Expanded(child:Text(p.name,style:Theme.of(context).textTheme.titleLarge)),PopupMenuButton<String>(onSelected:(v){if(v=='edit')editPlan(p);if(v=='delete')deletePlan(p);},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'delete',child:Text('Excluir'))])]),for(final d in p.weekdays)ListTile(contentPadding:EdgeInsets.zero,title:Text(weekDays[d-1]),subtitle:Text(p.exercisesFor(d).map((e)=>'${e.name} (${e.sets}×${e.reps})').join(', ')),trailing:IconButton(onPressed:()=>startWorkout(p,d),icon:const Icon(Icons.play_arrow)))])),if(plans.any((p)=>p.weekdays.contains(today)))const SizedBox(height:4),HistorySection(key:ValueKey(_historyRefresh))]));}}
