class _ExercisePickerState extends State<ExercisePicker>{late List<ExerciseInfo> list;String query='';String? selected;@override void initState(){super.initState();list=[...widget.library];}Future<void> create()async{final e=await widget.newExercise();if(e!=null&&mounted)setState((){list.add(e);selected=e['name'];});}@override Widget build(BuildContext context){final filtered=list.where((e)=>e['name']!.toLowerCase().contains(query.toLowerCase())).toList();final children=<Widget>[TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Pesquisar'),onChanged:(v)=>setState(()=>query=v))];for(final e in filtered){children.add(ListTile(title:Text(e['name']!),subtitle:Text(e['equipment']!.isEmpty?e['muscle']!:'${e['muscle']} • ${e['equipment']}'),selected:selected==e['name'],onTap:()=>setState(()=>selected=e['name'])));}return AlertDialog(title:const Text('Exercício'),content:SizedBox(width:450,height:420,child:ListView(children:children)),actions:[TextButton(onPressed:create,child:const Text('NOVO')),TextButton(onPressed:()=>Navigator.pop(context),child:const Text('CANCELAR')),FilledButton(onPressed:(){if(selected==null)return;final e=list.firstWhere((x)=>x['name']==selected);Navigator.pop(context,Exercise(id:DateTime.now().microsecondsSinceEpoch.toString(),name:e['name']!,muscle:e['muscle']!,sets:3,reps:10));},child:const Text('ADICIONAR'))]);}}
